import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Accessibilità","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/accessibilita.md","filePath":"user-guide/accessibilita.md"}'),t={name:"user-guide/accessibilita.md"};function n(s,e,c,l,d,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="accessibilita" tabindex="-1">Accessibilità <a class="header-anchor" href="#accessibilita" aria-label="Permalink to &quot;Accessibilità&quot;">​</a></h1><p>Lo stato dei controlli e le procedure di verifica sono in <code>docs/qa/a11y-desktop.md</code> e <code>docs/qa/a11y-web.md</code>. Non dichiariamo conformità WCAG: i controlli automatici (axe) non rilevano problemi gravi nelle schermate coperte, e restano da completare le verifiche manuali con screen reader reali.</p><h2 id="tastiera" tabindex="-1">Tastiera <a class="header-anchor" href="#tastiera" aria-label="Permalink to &quot;Tastiera&quot;">​</a></h2><ul><li>Tutta l&#39;interfaccia dell&#39;app si può usare da tastiera; <code>Mod+P</code> apre la palette con ogni comando.</li><li><strong>Schede della barra laterale e dei documenti:</strong> una sola sosta con <code>Tab</code>, poi frecce sinistra/destra, <code>Home</code>/<code>Fine</code>; <code>Canc</code> chiude una scheda del documento (non se è bloccata). I pulsanti della barra a icone (azioni rapide, intestazione, schede della barra destra) hanno un nome per gli screen reader e un suggerimento.</li><li><strong>Presentazioni:</strong> <code>Frecce</code>, <code>Spazio</code>, <code>Home</code>/<code>Fine</code> per scorrere le slide, <code>P</code> per la vista presentatore, <code>Esc</code> per uscire; il numero della slide corrente è annunciato.</li><li><strong>Albero dei file:</strong> frecce, <code>Invio</code>, <code>F2</code>, <code>Canc</code>, tasto Menu / <code>Maiusc+F10</code> (vedi <a href="./impostazioni-scorciatoie.html">Impostazioni e scorciatoie</a>).</li><li><strong>Finestre di dialogo e menu:</strong> il focus resta dentro la finestra, <code>Esc</code> chiude e il focus torna all&#39;elemento di partenza.</li><li><strong>Web UI:</strong> primo <code>Tab</code> = &quot;Vai al contenuto&quot;; ogni tabella ha didascalia e intestazioni; gli errori dei moduli sono collegati ai campi.</li></ul><h2 id="schermo-e-movimento" tabindex="-1">Schermo e movimento <a class="header-anchor" href="#schermo-e-movimento" aria-label="Permalink to &quot;Schermo e movimento&quot;">​</a></h2><ul><li><strong>Contrasto:</strong> i colori del testo rispettano il rapporto 4,5:1 in tema chiaro e scuro. Con la modalità <strong>contrasto elevato di Windows</strong> (colori forzati) l&#39;app usa i colori di sistema e mantiene visibili focus e scheda attiva.</li><li><strong>Movimento ridotto:</strong> se il sistema chiede di ridurre il movimento, animazioni e transizioni sono disattivate.</li><li><strong>Zoom:</strong> <em>Impostazioni → Aspetto</em> permette di ingrandire interfaccia e carattere; la Web UI si adatta (reflow) fino a 320 px di larghezza.</li></ul><h2 id="screen-reader" tabindex="-1">Screen reader <a class="header-anchor" href="#screen-reader" aria-label="Permalink to &quot;Screen reader&quot;">​</a></h2><p>L&#39;editor di testo espone un campo di testo multiriga etichettato (&quot;Editor della nota&quot;); la barra di stato facoltativa è una regione <code>status</code> che non annuncia i conteggi a ogni tasto (sarebbe rumore): per ascoltarli aprite la scheda <em>Statistiche</em> (<em>Mostra statistiche</em>); lo stato di salvataggio e di sincronizzazione è annunciato senza spostare il focus. Le superfici grafiche (grafo, lavagna, disegni) <strong>non</strong> hanno ancora un equivalente testuale completo: per il grafo usate backlink e struttura, per le lavagne le note incorporate. Il grafo, in 2D e in 3D, ha un&#39;etichetta, prende il focus e si usa da tastiera (frecce, <code>+</code>/<code>-</code>, <code>0</code>, <code>[</code> e <code>]</code> per passare da un nodo all&#39;altro, Invio per aprire; vedi <a href="./canvas-disegni-bases-grafo.html#vista-grafo">Vista grafo</a>), ma non elenca i nodi come testo; la vista 3D ha le stesse scorciatoie, con le frecce che ruotano la vista, e con «riduci movimento» attivo nel sistema la camera non si anima. Segnalateci i problemi che incontrate.</p><p><strong>Applicazioni</strong> (<a href="./applicazioni.html">guida</a>): la barra della scheda (indietro, avanti, ricarica, indirizzo, «Cambia indirizzo», «Apri nel browser»), gli avvisi sulla pagina, la conferma dell&#39;origine e i riquadri di errore sono pulsanti e riquadri con un nome per gli screen reader e rientrano nella scansione automatica di accessibilità (axe); gli avvisi sono una regione <code>aria-live</code> e i riquadri di errore sono <code>alert</code>. <strong>Non c&#39;è una verifica manuale con screen reader reali</strong> (come per il resto, vedi sopra). <strong>Il contenuto della pagina no:</strong> è quello del sito, mostrato dal browser del sistema in una vista separata, e la sua accessibilità non è verificata. Il pulsante «Apri nel browser» porta la stessa pagina nel browser predefinito.</p>',9)])])}const g=a(t,[["render",n]]);export{p as __pageData,g as default};
